CREATE OR ALTER PROCEDURE [dbo].[ACTION_ENGAGED] @ID_ACTION int, @ID_MODULE int AS BEGIN -- 1 ENGAGED -- 0 NOT ENGAGED DECLARE @CNT int if (@ID_MODULE is not null) SELECT @CNT = COUNT(*) FROM POSTE_COUT_ENGAGE INNER JOIN ENGAGEMENT ON POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT AND ENGAGEMENT.ID_TYPE_ENGAGEMENT <> 2 AND ENGAGEMENT.DAT_BAE IS NOT NULL WHERE POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE AND POSTE_COUT_ENGAGE.MNT_ENGAGE_HT >= 0 AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT is null else if (@ID_ACTION is not null) SELECT @CNT = COUNT(*) FROM MODULE_PEC INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ACTION_PEC = @ID_ACTION AND ENGAGEMENT.ID_TYPE_ENGAGEMENT <> 2 AND ENGAGEMENT.DAT_BAE IS NOT NULL INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT AND POSTE_COUT_ENGAGE.MNT_ENGAGE_HT >= 0 AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT is null WHERE (MODULE_PEC.ID_ACTION_PEC = @ID_ACTION) else SELECT @CNT = COUNT(*) FROM MODULE_PEC INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC AND ENGAGEMENT.ID_TYPE_ENGAGEMENT <> 2 AND ENGAGEMENT.DAT_BAE IS NOT NULL INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT AND POSTE_COUT_ENGAGE.MNT_ENGAGE_HT >= 0 AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT is null
/* SELECT @CNT = COUNT(*) FROM ACTION_PEC INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC AND ENGAGEMENT.ID_TYPE_ENGAGEMENT <> 2 AND ENGAGEMENT.DAT_BAE IS NOT NULL INNER JOIN MODULE_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC AND ( (ACTION_PEC.ID_ACTION_PEC = @ID_ACTION OR @ID_ACTION IS NULL) AND (MODULE_PEC.ID_MODULE_PEC = @ID_MODULE OR @ID_MODULE IS NULL) ) INNER JOIN POSTE_COUT_ENGAGE ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT AND POSTE_COUT_ENGAGE.MNT_ENGAGE_HT >= 0 AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT is null
select @CNT AS MODIFIABLE */ select @CNT AS ENGAGED return @CNT END
